{:db/id 17592186184153 :knowledge-point/canonical-example {:db/id 17592186184057 :question/id #uuid "e4a94ca8-82ee-5776-a46d-b735d4ab60fb" :question/math-academy-id "e-371" :question/problem "Find the integral of $x^2 + 1.$" :question/worked-solution "Applying the sum rule, we compute the sum of the integrals of each function:

$$
\begin{aligned}\int {x}^{2}+1\,\text{d}x & =\int {x}^{2}\,\text{d}x+\int 1\,\text{d}x \\  & =\int {x}^{2}\,\text{d}x+\int {x}^{0}\,\text{d}x \\  & =\left(\frac{{x}^{2+1}}{2+1}\right)+x+C \\  & =\frac{1}{3}{x}^{3}+x+C\end{aligned}
$$"} :knowledge-point/id #uuid "0db9b1c3-1e31-53f6-9fc2-1c611e2f9398" :knowledge-point/key-prerequisites [{:db/id 17592186049481 :topic/id #uuid "f8a6d16e-1a41-5d40-8c3d-467ebdcc3782" :topic/knowledge-points [{:db/id 17592186064167} {:db/id 17592186064168} {:db/id 17592186064169}] :topic/math-academy-id 308 :topic/next [{:db/id 17592186048442} {:db/id 17592186050057}] :topic/title "The Antiderivative"}] :knowledge-point/questions [{:db/id 17592186184549 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "874a75be-05b5-5213-a317-ac84d079a6f8" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{\sqrt{x^{3}}}{3} - 3x + C" :db/id 17592186181463} {:answer/id #uuid "b4254b4e-b369-5812-943b-4e67411913f0" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{3\sqrt[3]{x^{2}}}{2} - 3x" :db/id 17592186181464} {:answer/id #uuid "b8145e65-a4e6-55ed-84fd-bcbca085060c" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{3x\sqrt{x^{3}}}{2} - 3x + C" :db/id 17592186181465} {:answer/id #uuid "1f4f8890-7502-5e8c-90d6-f4aba9048241" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{2x\sqrt[3]{x}}{3} + 3 + C" :db/id 17592186181466} {:answer/id #uuid "461e199a-4bf9-5631-92ee-54bbc39d5458" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{2\sqrt{x^{3}}}{3} - 3x + C" :db/id 17592186181467}] :answer-field/id #uuid "14660fe1-ec5a-5be7-8fe4-11781606df39" :answer-field/key "selection" :answer-field/type {:db/ident :answer-field.type/radio} :db/id 17592186181462}] :question/id #uuid "ebf755a0-1ba0-54d7-8cfa-097d44473af4" :question/math-academy-id "q-2159" :question/problem "What is $\displaystyle \int\sqrt{x} - 3dx$?"} {:db/id 17592186184738 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "9836b573-d927-50b1-b2a4-0ccf3e742d92" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{2\sqrt{x^{7}}}{7} - \frac{2}{3\sqrt{x^{3}}} + C" :db/id 17592186183043} {:answer/id #uuid "b7835897-2660-52c4-b